    /// One line, English, for a developer. Never shown to a user.
    #[must_use]
    pub const fn description(self) -> &'static str {
        match self {
            Self::BlobMalformedHash => "A blob was named by text that is not a BLAKE3 hash",
            Self::BlobNotLocal => "A blob is not on this machine",
            Self::BlobTooLarge => "A blob grew past the size the kernel accepts",
            Self::BlobIo => "Reading or writing a blob's bytes on this machine failed",
            Self::BlobWriterFinished => {
                "A blob writer was written to or finished after it had finished"
            }
            Self::BlobNoPeers => "A blob was announced and no peer was there to tell",
            Self::CanonUnparsable => "A payload is not the canonical form this platform carries",
            Self::CanonNumber => "A payload holds a number this model cannot represent",
            Self::ChannelManifestUnreadable => {
                "An install manifest is not one this build reads: not a JSON object, a key it does not know or lacks, a value of the wrong type, or another format"
            }
            Self::ChannelUnknown => "An install manifest names a channel this build does not know",
            Self::ChannelCheckoutMalformed => {
                "An install manifest's checkout is missing from a development install, present in another channel's, or not eight lower-case hexadecimal digits"
            }
            Self::ChannelBaseMalformed => {
                "An install manifest names a base directory that is not a plain absolute path"
            }
            Self::ChannelNamespaceMalformed => {
                "An install manifest's namespace is not one to sixteen lower-case letters and digits holding a digit"
            }
            Self::DbUnreachable => "The database did not answer",
            Self::DbMigrationFailed => "A migration failed to apply",
            Self::DbPruneFailed => "Pruning a table did not finish, and a later run may",
            Self::DbTableNotBounded => {
                "A table cannot be pruned the way the request asks, so it was left alone"
            }
            Self::DbPruneRefused => "Pruning a table was refused, and retrying will not change it",
            Self::DbLocalOpenRefused => {
                "The local database's folder or files are not set up for this user alone to read and write, so it was not opened"
            }
            Self::DbLocalSchemaUnexpected => {
                "The local database is not the one this build expects, so it was not used"
            }
            Self::IdsClockBackwards => {
                "The clock moved backwards, so minting would repeat an identifier it has issued"
            }
            Self::IdsSequenceExhausted => {
                "This millisecond's sequence was exhausted and minting waited"
            }
            Self::IdsFlakeExhausted => {
                "Every machine-flake candidate in the sequence was already taken"
            }
            Self::IdsNameUnparsable => "A file name does not parse as the naming scheme",
            Self::IdsNameTooLong => "A file name cannot be built within the filesystem's limits",
            Self::IdsNotAnIdentifier => "Text handed to an identifier type is not one",
            Self::IdsClockStuck => {
                "The clock has stopped, so no more identifiers can be minted on this machine"
            }
            Self::IdsClockOutOfRange => {
                "The clock is outside the range this identifier layout can represent"
            }
            Self::JournalChainBroken => "The journal's hash chain is broken at an entry",
            Self::JournalEntryTampered => "An entry's hash does not match the entry's own contents",
            Self::JournalUnavailable => "The journal store did not answer",
            Self::JournalUnitClosed => {
                "A work unit that was already committed or aborted received an entry"
            }
            Self::JournalUnstorable => {
                "A record holds something no store could keep, so it was refused before the store saw it"
            }
            Self::JournalContended => {
                "Another writer took this sequence first, so the entry was not written"
            }
            Self::JournalUnitAlreadyOpen => "A work unit that is already open was opened again",
            Self::JournalSequenceAhead => {
                "An entry was numbered past the end of the history, which no other writer can cause"
            }
            Self::JournalRefused => {
                "The journal store answered and refused the write: a grant, a schema or a role, not an outage"
            }
            Self::JournalUnitNeverOpened => "A work unit that was never opened was asked to close",
            Self::KernelUnknownCommand => {
                "A dispatch named a command no built-in and no activated plugin declares"
            }
            Self::KernelMalformedName => {
                "A dispatch named a command in a shape no command name can have"
            }
            Self::KernelReentrant => {
                "A plugin dispatched into itself while it was still running, which the kernel refuses rather than traps"
            }
            Self::KernelTooDeep => {
                "A call tree nested its dispatches deeper than the kernel allows"
            }
            Self::KernelReadOnly => {
                "A command that changes state was dispatched where only reading is allowed"
            }
            Self::KernelUnconfirmed => {
                "An irreversible command was dispatched without a confirmation the kernel issued"
            }
            Self::KernelDeadline => "A call tree ran past its deadline and was stopped",
            Self::KernelUnitAborted => "A unit of work was aborted, so nothing it did was kept",
            Self::KernelNothingToUndo => "An undo found no step of this person's to reverse",
            Self::KernelNothingToRedo => "A redo found no undone step of this person's to restore",
            Self::KernelUndoConflict => {
                "An undo or a redo was refused because what it would put back has been changed since"
            }
            Self::KernelUndoBarrier => {
                "An undo reached a step that left the machine or cannot be undone, with nothing registered to reverse it"
            }
            Self::KernelRedoCompensated => {
                "A redo was refused because the undo it would reverse dispatched compensating commands"
            }
            Self::KernelCompensationFailed => {
                "An undo stopped because a compensating command it dispatched failed"
            }
            Self::KernelNameTaken => {
                "A plugin declared a command or a topic outside its namespace, in a reserved one, twice, or as a catalog command it does not match"
            }
            Self::KernelRecoveredUnit => {
                "A unit of work a stopped process left open was reverted when the kernel opened"
            }
            Self::KernelTopLevelOnly => {
                "Undo or redo was dispatched from inside another command, where neither may run"
            }
            Self::KernelNotBuilt => {
                "A plugin granted a capability called a host function of it this build of the kernel does not implement"
            }
            Self::KernelRedoBlobSwept => {
                "A redo was refused because a blob the step created has been swept since"
            }
            Self::KernelTooManyDispatches => {
                "A call tree dispatched more commands than the kernel allows one tree"
            }
            Self::KernelCompensationRefused => {
                "A compensation was refused because the command it names cannot set a step right: it changes nothing, needs a person's confirmation or a quorum's approval, or is one of the kernel's own, undo and redo among them"
            }
            Self::KernelStepUnrecorded => {
                "An undo or a redo was refused because the journal does not record as kept the step it would reverse"
            }
            Self::KernelCompensationMoved => {
                "An undo was refused because a command its step registered as a compensation is no longer held by the plugin that held it then"
            }
            Self::KernelCompensationUngranted => {
                "An undo was refused because a compensation its step registered names another plugin's command, and the plugin that registered it is no longer loaded granted commands.dispatch"
            }
            Self::LogUnreachable => "The central log store did not accept a batch",
            Self::LogDropped => "Log events were dropped because the queue was full",
            Self::PluginCapabilityDenied => {
                "A plugin called a host function of a capability its manifest was not granted"
            }
            Self::PluginTrapped => "A plugin trapped, and was killed and restarted",
            Self::PluginOutOfFuel => {
                "A plugin computed past its fuel, and was killed and restarted"
            }
            Self::PluginEpochDeadline => {
                "A plugin ran past its epoch deadline, and was killed and restarted"
            }
            Self::PluginMemoryLimit => {
                "A plugin grew past its memory limit, and was killed and restarted"
            }
            Self::PluginHostCallDeadline => {
                "A host function a plugin called ran past its deadline, and the plugin was killed and restarted"
            }
            Self::PluginQuarantined => {
                "A plugin is quarantined until it is released: it crashed too often inside its restart window, or did not come back as it was"
            }
            Self::PluginDescriptorMissingField => {
                "A command a plugin declared at activate lacks a field every command needs"
            }
            Self::PluginDescriptorInvalid => {
                "A command or a subscription a plugin declared at activate is refused"
            }
            Self::PluginManifestInvalid => {
                "A plugin's manifest is refused: not one, asking for what the catalog does not declare, or raising a limit"
            }
            Self::PluginComponentInvalid => {
                "A plugin's component does not compile, or does not link against the world"
            }
            Self::PluginDomainNotDeclared => {
                "A plugin fetched from a domain its manifest does not declare"
            }
            Self::PluginRequestRefused => {
                "A plugin's network request is refused for its scheme, address, port, headers or method"
            }
            Self::PluginResponseTooLarge => "A network response was larger than the kernel accepts",
            Self::PluginNetworkUnavailable => {
                "A network request did not complete: no answer, a timeout, or a connection that failed"
            }
            Self::PluginUiInvalid => "A plugin rendered a surface the kernel refuses",
            Self::PluginBoundReached => {
                "A plugin reached a bound the catalog declares: a quota, a queue or a count"
            }
            Self::PluginStoreConflict => {
                "A write was refused because what it expected to replace had changed"
            }
            Self::PluginNotFound => {
                "A plugin asked for a key, a timer, a surface or a command that is not there"
            }
            Self::PluginMalformedResult => {
                "A plugin answered with a result that is not canonical, or that is too large"
            }
            Self::PluginActivationFailed => {
                "A plugin did not activate: it trapped, ran out of fuel, outgrew its memory or refused while it was instantiated or activated"
            }
            Self::PluginIdentityTaken => {
                "A plugin was not loaded: its identity or its namespace is held by a loaded plugin, or its namespace is one the kernel keeps"
            }
            Self::PluginCommandRefused => {
                "A plugin's command refused what it was asked, answering one of the world's errors in its own words"
            }
            Self::PluginReadOnlyFrame => {
                "A plugin wrote where only reading is allowed — in activate, a callback or a command declared a read — or dispatched from activate, where no command runs"
            }
            Self::PluginOutsideACallTree => {
                "A plugin called, where no call tree runs, a host function that acts for the person one runs for: the context, an event, a timer or a surface"
            }
            Self::PluginTopicRefused => {
                "A plugin published an event under a topic that is not one, or that is outside its namespace"
            }
            Self::PluginNotARevision => {
                "A plugin's write named, as the revision it expects to replace, text that is not a revision"
            }
            Self::PluginUnitEnded => {
                "A plugin called a method on the handle of a unit that had ended — aborted, let go, or begun in a command that has returned — and the call did nothing"
            }
            Self::PolicyUnreadable => "A policy pack could not be read",
            Self::PolicyInvalid => "A policy pack does not validate against the Cedar schema",
            Self::PolicyDenied => "The decision point denied a request",
            Self::PolicyPackNotCarried => "A realm pins a policy pack this build does not carry",
            Self::PolicyEvaluationFailed => {
                "A decision could not be evaluated: the request does not fit the schema, or a policy erred"
            }
            Self::PolicyDirectoryUnavailable => {
                "The directory the decision point reads realms, grants and entities from did not answer"
            }
            Self::PolicyRuleBroken => "A policy pack breaks a rule packs are held to",
            Self::ValidationOutOfRange => {
                "A value is outside the limit the catalog declares for it"
            }
            Self::ValidationArgumentsInvalid => {
                "A command's arguments do not validate against the schema it declares"
            }
            Self::ValidationResourceIdMalformed => {
                "The identifier a command's resource selector took from its arguments is not one"
            }
        }
    }

